do $$begin if current_setting('server_version_num')::integer<150000 then raise exception 'PostgreSQL 15+ obrigatório';end if;if to_regprocedure('erp_security.has_permission_at_aal(uuid,text,text)')is null or to_regclass('public.erp_assets')is null or to_regclass('public.erp_parties')is null then raise exception 'M04/M05/M09 ausente';end if;if to_regclass('public.erp_support_tickets')is not null then raise exception 'Objetos M11 já existem sem histórico 0028';end if;if exists(select 1 from public.erp_permissions where(key like 'support.%'or key like 'remote.%')and category not in('Atendimento','Acesso remoto'))then raise exception 'Colisão de permissões M11';end if;end$$;
select now()checked_at,'M11_PREFLIGHT_OK'result;
